def alpha_unicode_split(decoded_sequence: str) -> list[str]:
    """
    Given a decoded text sequence, return a list of str. Unicode range / alphabet separation.
    Ex. a text containing English/Latin with a bit a Hebrew will return two items in the resulting list;
    One containing the latin letters and the other hebrew.
    """
    layers: dict[(str, list[str])] = {}
    single_layer_key: str | None = None
    multi_layer: bool = False
    prev_character_range: str | None = None
    prev_layer_target: str | None = None
    for character in decoded_sequence:
        codepoint: int = ord(character)
        if codepoint < 128:
            info = _ASCII_CHAR_INFO[codepoint]
        else:
            info = _char_info(character)
        if not info.alpha:
            continue
        character_range: str | None = info.range
        if character_range is None:
            continue
        if character_range == prev_character_range:
            if prev_layer_target is not None:
                layers[prev_layer_target].append(character)
            continue
        layer_target_range: str | None = None
        if multi_layer:
            for discovered_range in layers:
                if not is_suspiciously_successive_range(discovered_range, character_range):
                    layer_target_range = discovered_range
                    break
        elif single_layer_key is not None:
            if not is_suspiciously_successive_range(single_layer_key, character_range):
                layer_target_range = single_layer_key
        if layer_target_range is None:
            layer_target_range = character_range
        if layer_target_range not in layers:
            layers[layer_target_range] = []
            if single_layer_key is None:
                single_layer_key = layer_target_range
            else:
                multi_layer = True
        layers[layer_target_range].append(character)
        prev_character_range = character_range
        prev_layer_target = layer_target_range
    return [''.join(chars).lower() for chars in layers.values()]

charset_normalizer.md.is_suspiciously_su:
@lru_cache(maxsize=1024)
def is_suspiciously_successive_range(unicode_range_a: str | None, unicode_range_b: str | None) -> bool:
    """
    Determine if two Unicode range seen next to each other can be considered as suspicious.
    """
    if (unicode_range_a is None or unicode_range_b is None):
        return True
    if unicode_range_a == unicode_range_b:
        return False
    if ('Latin' in unicode_range_a and 'Latin' in unicode_range_b):
        return False
    if ('Emoticons' in unicode_range_a or 'Emoticons' in unicode_range_b):
        return False
    if ((('Latin' in unicode_range_a or 'Latin' in unicode_range_b)) and (('Combining' in unicode_range_a or 'Combining' in unicode_range_b))):
        return False
    (keywords_range_a, keywords_range_b) = (unicode_range_a.split(' '), unicode_range_b.split(' '))
    for el in keywords_range_a:
        if el in UNICODE_SECONDARY_RANGE_KEYWORD:
            continue
        if el in keywords_range_b:
            return False
    (range_a_jp_chars, range_b_jp_chars) = (unicode_range_a in ('Hiragana', 'Katakana'), unicode_range_b in ('Hiragana', 'Katakana'))
    if (((range_a_jp_chars or range_b_jp_chars)) and (('CJK' in unicode_range_a or 'CJK' in unicode_range_b))):
        return False
    if (range_a_jp_chars and range_b_jp_chars):
        return False
    if ('Hangul' in unicode_range_a or 'Hangul' in unicode_range_b):
        if ('CJK' in unicode_range_a or 'CJK' in unicode_range_b):
            return False
        if (unicode_range_a == 'Basic Latin' or unicode_range_b == 'Basic Latin'):
            return False
    if (('CJK' in unicode_range_a or 'CJK' in unicode_range_b) or (unicode_range_a in ['Katakana', 'Hiragana'] and unicode_range_b in ['Katakana', 'Hiragana'])):
        if ('Punctuation' in unicode_range_a or 'Punctuation' in unicode_range_b):
            return False
        if ('Forms' in unicode_range_a or 'Forms' in unicode_range_b):
            return False
        if (unicode_range_a == 'Basic Latin' or unicode_range_b == 'Basic Latin'):
            return False
    return True

charset_normalizer.cd.characters_popular:
def characters_popularity_compare(language: str, ordered_characters: list[str]) -> float:
    """
    Determine if a ordered characters list (by occurrence from most appearance to rarest) match a particular language.
    The result is a ratio between 0. (absolutely no correspondence) and 1. (near perfect fit).
    Beware that is function is not strict on the match in order to ease the detection. (Meaning close match is 1.)
    """
    if language not in FREQUENCIES:
        raise ValueError(f'{language} not available')
    character_approved_count: int = 0
    lang_rank: dict[(str, int)] = _FREQUENCIES_RANK[language]
    ordered_characters_count: int = len(ordered_characters)
    target_language_characters_count: int = len(FREQUENCIES[language])
    large_alphabet: bool = target_language_characters_count > 26
    large_alphabet_threshold: float = target_language_characters_count / 3
    expected_projection_ratio: float = target_language_characters_count / ordered_characters_count
    common_lr: list[int] = []
    common_orr: list[int] = []
    for (popularity_rank, character) in enumerate(ordered_characters):
        language_rank = lang_rank.get(character)
        if language_rank is not None:
            common_lr.append(language_rank)
            common_orr.append(popularity_rank)
    for (character_rank_in_language, character_rank) in zip(common_lr, common_orr):
        character_rank_projection: int = int(character_rank * expected_projection_ratio)
        if (not large_alphabet and abs(character_rank_projection - character_rank_in_language) > 4):
            continue
        if (large_alphabet and abs(character_rank_projection - character_rank_in_language) < large_alphabet_threshold):
            character_approved_count += 1
            continue
        if character_rank_in_language == 0:
            character_approved_count += 1
            continue
        after_len: int = target_language_characters_count - character_rank_in_language
        before_match_count: int = 0
        after_match_count: int = 0
        for (lr_i, orr_i) in zip(common_lr, common_orr):
            if lr_i < character_rank_in_language:
                if orr_i < character_rank:
                    before_match_count += 1
                    if 5 * before_match_count >= 2 * character_rank_in_language:
                        character_approved_count += 1
                        break
            elif orr_i >= character_rank:
                after_match_count += 1
                if 5 * after_match_count >= 2 * after_len:
                    character_approved_count += 1
                    break
    return character_approved_count / len(ordered_characters)

charset_normalizer.cd.coherence_ratio:
def coherence_ratio(decoded_sequence: str, threshold: float = 0.1, lg_inclusion: str | None = None) -> CoherenceMatches:
    """
    Detect ANY language that can be identified in given sequence. The sequence will be analysed by layers.
    A layer = Character extraction by alphabets/ranges.
    """
    results: list[tuple[(str, float)]] = []
    ignore_non_latin: bool = False
    sufficient_match_count: int = 0
    lg_inclusion_list = (lg_inclusion.split(',') if lg_inclusion is not None else [])
    if 'Latin Based' in lg_inclusion_list:
        ignore_non_latin = True
        lg_inclusion_list.remove('Latin Based')
    for layer in alpha_unicode_split(decoded_sequence):
        char_counts: dict[(str, int)] = {}
        for layer_character in layer:
            char_counts[layer_character] = char_counts.get(layer_character, 0) + 1
        character_count: int = len(layer)
        if character_count <= TOO_SMALL_SEQUENCE:
            continue
        popular_character_ordered: list[str] = [item[0] for item in sorted(char_counts.items(), key=lambda item: item[1], reverse=True)]
        for language in (lg_inclusion_list or alphabet_languages(popular_character_ordered, ignore_non_latin)):
            ratio: float = characters_popularity_compare(language, popular_character_ordered)
            if ratio < threshold:
                continue
            elif ratio >= 0.8:
                sufficient_match_count += 1
            results.append((language, round(ratio, 4)))
            if sufficient_match_count >= 3:
                break
    return sorted(filter_alt_coherence_matches(results), key=lambda x: x[1], reverse=True)

urllib3.contrib.emscripten.fetch.streami:
def streaming_ready() -> bool | None:
    if _fetcher:
        return _fetcher.streaming_ready
    else:
        return None

urllib3.contrib.emscripten.fetch.send_st:
def send_streaming_request(request: EmscriptenRequest) -> EmscriptenResponse | None:
    if has_jspi():
        return send_jspi_request(request, True)
    elif is_in_node():
        raise _RequestError(message=NODE_JSPI_ERROR, request=request, response=None)
    if (_fetcher and streaming_ready()):
        return _fetcher.send(request)
    else:
        _show_streaming_warning()
        return None

urllib3.contrib.emscripten.fetch._show_s:
def _show_streaming_warning() -> None:
    global _SHOWN_STREAMING_WARNING
    if not _SHOWN_STREAMING_WARNING:
        _SHOWN_STREAMING_WARNING = True
        message = "Can't stream HTTP requests because: \n"
        if not is_cross_origin_isolated():
            message += '  Page is not cross-origin isolated\n'
        if is_in_browser_main_thread():
            message += '  Python is running in main browser thread\n'
        if not is_worker_available():
            message += ' Worker or Blob classes are not available in this environment.'
        if streaming_ready() is False:
            message += " Streaming fetch worker isn't ready. If you want to be sure that streaming fetch\nis working, you need to call: 'await urllib3.contrib.emscripten.fetch.wait_for_streaming_ready()`"
        from js import console
        console.warn(message)

idna.core.ulabel:
def ulabel(label: Union[(str, bytes, bytearray)]) -> str:
    """Convert a single A-label into its U-label form.

    Performs the inverse of :func:`alabel`: an ``xn--``-prefixed label is
    Punycode-decoded and validated. Labels that are already Unicode (or
    plain ASCII without the ACE prefix) are validated and returned as a
    Unicode string.

    :param label: The label to convert. ``bytes`` or ``bytearray`` input
        is treated as ASCII.
    :returns: The U-label as a Unicode string.
    :raises IDNAError: If the label is malformed or fails validation.
    """
    if len(label) > _max_input_length:
        raise IDNAError('Label too long')
    if not isinstance(label, (bytes, bytearray)):
        try:
            label_bytes = label.encode('ascii')
        except UnicodeEncodeError:
            check_label(label)
            return label
    else:
        label_bytes = bytes(label)
    label_bytes = label_bytes.lower()
    if label_bytes.startswith(_alabel_prefix):
        label_bytes = label_bytes[len(_alabel_prefix):]
        if not label_bytes:
            raise IDNAError('Malformed A-label, no Punycode eligible content found')
        if label_bytes.endswith(b'-'):
            raise IDNAError('A-label must not end with a hyphen')
    else:
        check_label(label_bytes)
        return label_bytes.decode('ascii')
    try:
        label = label_bytes.decode('punycode')
    except UnicodeError as err:
        raise IDNAError('Invalid A-label') from err
    check_label(label)
    return label

urllib3.util.wait.select_wait_for_socket:
def select_wait_for_socket(sock: socket.socket, read: bool = False, write: bool = False, timeout: float | None = None) -> bool:
    if (not read and not write):
        raise RuntimeError('must specify at least one of read=True, write=True')
    rcheck = []
    wcheck = []
    if read:
        rcheck.append(sock)
    if write:
        wcheck.append(sock)
    fn = partial(select.select, rcheck, wcheck, wcheck)
    (rready, wready, xready) = fn(timeout)
    return bool((rready or wready or xready))
